export type Product = { sku: string; name: string; priceCents: number; stock: number };

function show(p: Product): string {
  return `${p.sku} ${p.name}: $${(p.priceCents / 100).toFixed(2)}, ${p.stock} in stock`;
}

export function applyPatch(p: Product, patch: Partial<Product>): Product {
  return { ...p, ...patch };
}

const mug: Product = { sku: "MUG-01", name: "Mug", priceCents: 1299, stock: 4 };
