steps.body:
Data rarely crosses an edge of your code in its full shape. A create function takes the record without the fields the server makes, and a list shows a few fields per item. These shapes are often called DTOs, data transfer objects. Build them from the full type, so they follow it when it changes:

- `Omit<T, K>` is `T` without the keys in `K`. `Omit<User, "id" | "createdAt">` is a create input.
- `Pick<T, K>` keeps only the keys in `K`. `Pick<User, "id" | "name">` is a list item.
- `Record<K, V>` is an object with every key in `K`, each holding a `V`.

```typescript types
type User = { id: number; name: string; email: string; createdAt: string };

type NewUser = Omit<User, "id" | "createdAt">;
//   ^? type NewUser = { name: string; email: string; }
type UserSummary = Pick<User, "id" | "name">;
//   ^? type UserSummary = { id: number; name: string; }
```

`Pick` only takes keys the type has, so a typo in one is an error. `Omit` takes any string, so `Omit<User, "createdat">` quietly removes nothing. Check the spelling of what you omit.

examples.code:
type User = { id: number; name: string; email: string; createdAt: string };
type NewUser = Omit<User, "id" | "createdAt">;

function createUser(input: NewUser, id: number, now: string): User {
  return { id, ...input, createdAt: now };
}

const ada = createUser({ name: "Ada", email: "ada@example.com" }, 1, "2026-10-01T09:00:00Z");
const grace = createUser({ name: "Grace", email: "grace@example.com" }, 2, "2026-10-01T09:05:00Z");

console.log(JSON.stringify(ada));
console.log(JSON.stringify(grace));

type User = { id: number; name: string; email: string; createdAt: string };
type UserSummary = Pick<User, "id" | "name">;

function summarize(user: User): UserSummary {
  return { id: user.id, name: user.name };
}

const users: User[] = [
  { id: 1, name: "Ada", email: "ada@example.com", createdAt: "2026-10-01T09:00:00Z" },
  { id: 2, name: "Grace", email: "grace@example.com", createdAt: "2026-10-01T09:05:00Z" },
];

const summaries = users.map(summarize);
//    ^? const summaries: UserSummary[]

for (const s of summaries) {
  console.log(`#${s.id} ${s.name}`);
}
console.log(JSON.stringify(summaries));

