export type Task = { id: number; title: string; done: boolean; createdAt: string };

export type NewTask = Omit<Task, "id" | "done" | "createdAt">;

function show(t: Task): string {
  return `${t.id}. ${t.title} (${t.done ? "done" : "open"}, created ${t.createdAt})`;
}

export function createTask(input: NewTask, id: number, now: string): Task {
  return { id, ...input, done: false, createdAt: now };
}

const report = createTask({ title: "Write the report" }, 1, "2026-10-01T09:00:00Z");
const venue = createTask({ title: "Book the venue" }, 2, "2026-10-01T09:30:00Z");

console.log(show(report));
console.log(show(venue));

steps.body:
Some utility types filter a union instead of an object. They check each member of the union and keep it or drop it:

- `Exclude<T, U>` drops the members of `T` that fit `U`.
- `Extract<T, U>` keeps only the members that fit `U`. `U` can be a shape, like `{ type: "click" }`, to pick members of a tagged union.
- `NonNullable<T>` drops `null` and `undefined`.

```typescript types
type Status = "draft" | "published" | "archived";

type Visible = Exclude<Status, "archived">;
//   ^? type Visible = "draft" | "published"
type Finished = Extract<Status, "published" | "archived">;
//   ^? type Finished = "archived" | "published"
type Name = NonNullable<string | null | undefined>;
//   ^? type Name = string
```

The bubbles list the members in an order of TypeScript's choosing, and a union means the same in any order. Like every type, these filters are gone at runtime, so when values need filtering too, pair the type with a check, such as a type predicate.

examples.code:
type TicketStatus = "new" | "assigned" | "waiting" | "solved" | "closed";
type ActiveStatus = Exclude<TicketStatus, "solved" | "closed">;
//   ^? type ActiveStatus = "assigned" | "new" | "waiting"

function isActive(status: TicketStatus): status is ActiveStatus {
  return status !== "solved" && status !== "closed";
}

function nextStep(status: ActiveStatus): string {
  switch (status) {
    case "new":
      return "assign an agent";
    case "assigned":
      return "reply to the customer";
    case "waiting":
      return "follow up in two days";
  }
}

const statuses: TicketStatus[] = ["new", "solved", "waiting", "closed", "assigned"];
for (const s of statuses) {
  console.log(isActive(s) ? `${s}: ${nextStep(s)}` : `${s}: nothing to do`);
}

type UiEvent =
  | { type: "click"; x: number; y: number }
  | { type: "keypress"; key: string }
  | { type: "scroll"; offset: number };

type ClickEvent = Extract<UiEvent, { type: "click" }>;
//   ^? type ClickEvent = { type: "click"; x: number; y: number; }

function describeClick(e: ClickEvent): string {
  return `click at ${e.x},${e.y}`;
}

const events: UiEvent[] = [
  { type: "keypress", key: "a" },
  { type: "click", x: 10, y: 20 },
  { type: "scroll", offset: 300 },
  { type: "click", x: 5, y: 8 },
];

for (const e of events) {
  if (e.type === "click") {
    console.log(describeClick(e));
  }
}

function compact<T>(xs: readonly (T | null | undefined)[]): NonNullable<T>[] {
  return xs.filter((x) => x !== null && x !== undefined);
}

const names = compact(["Ada", null, "Grace", undefined, "Linus"]);
//    ^? const names: string[]
const ports = compact([8080, undefined, 0, 3000]);
//    ^? const ports: number[]

console.log(names.join(", "));
console.log(ports.join(", "));

