steps.body:
Sometimes the code comes first: a function already returns the shape you need. Derive the type from it instead of writing it again, and the two can never disagree. In a type position, `typeof loadConfig` is the function's type, and three utility types take it apart:

- `ReturnType<F>` is what `F` returns.
- `Parameters<F>` is a tuple of its parameter types, so `Parameters<F>[0]` is the first one.
- `Awaited<T>` is what a promise resolves to, so `Awaited<ReturnType<F>>` unwraps an async function's result.

```typescript
function loadConfig() {
  return { port: 8080, host: "localhost" };
}

type Config = ReturnType<typeof loadConfig>;
//   ^? type Config = { port: number; host: string; }
```

These utility types take a type, not a value. `ReturnType<loadConfig>` is an error that asks whether you meant `typeof loadConfig`.

examples.code:
function loadConfig(env: Record<string, string>) {
  return {
    host: env["HOST"] ?? "localhost",
    port: Number(env["PORT"] ?? "3000"),
    debug: env["DEBUG"] === "1",
  };
}

type Config = ReturnType<typeof loadConfig>;
//   ^? type Config = { host: string; port: number; debug: boolean; }

function describe(config: Config): string {
  return `${config.host}:${config.port}${config.debug ? " (debug)" : ""}`;
}

console.log(describe(loadConfig({})));
console.log(describe(loadConfig({ PORT: "8080", DEBUG: "1" })));

function sendEmail(to: string, message: { subject: string; urgent: boolean }): string {
  return `${message.urgent ? "URGENT " : ""}to ${to}: ${message.subject}`;
}

type EmailArgs = Parameters<typeof sendEmail>;
//   ^? type EmailArgs = [to: string, message: { subject: string; urgent: boolean; }]
type Message = EmailArgs[1];
//   ^? type Message = { subject: string; urgent: boolean; }

const reminder: Message = { subject: "Your invoice", urgent: false };

const queue: EmailArgs[] = [
  ["ada@example.com", reminder],
  ["ops@example.com", { subject: "Disk almost full", urgent: true }],
];

for (const args of queue) {
  console.log(sendEmail(...args));
}

const USERS = [
  { id: 1, name: "Ada", plan: "pro" },
  { id: 2, name: "Grace", plan: "free" },
];

async function fetchUser(id: number) {
  const user = USERS.find((u) => u.id === id);
  if (user === undefined) {
    throw new Error(`no user ${id}`);
  }
  return user;
}

type Pending = ReturnType<typeof fetchUser>;
//   ^? type Pending = Promise<{ id: number; name: string; plan: string; }>
type User = Awaited<ReturnType<typeof fetchUser>>;
//   ^? type User = { id: number; name: string; plan: string; }

function badge(user: User): string {
  return `${user.name} [${user.plan}]`;
}

console.log(badge(await fetchUser(1)));
console.log(badge(await fetchUser(2)));

