practice.solution:
type Line = { description: string; qty: number; unitCents: number };

export function makeInvoice(customer: string, lines: Line[]) {
  const totalCents = lines.reduce((sum, line) => sum + line.qty * line.unitCents, 0);
  return { customer, lines, totalCents, currency: "USD" };
}

export type Invoice = ReturnType<typeof makeInvoice>;

function dollars(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

export function formatInvoice(inv: Invoice): string {
  const rows = inv.lines.map(
    (line) => `  ${line.qty} x ${line.description}: ${dollars(line.qty * line.unitCents)}`
  );
  return [`Invoice for ${inv.customer}`, ...rows, `Total: ${dollars(inv.totalCents)} ${inv.currency}`].join("\n");
}

const invoice = makeInvoice("Ada Lovelace", [
  { description: "Notebook", qty: 2, unitCents: 450 },
  { description: "Fountain pen", qty: 1, unitCents: 2599 },
]);
console.log(formatInvoice(invoice));
